// CSD_RATIONALE_BEGIN
// Diagnosis of 52%→41% regression (attempts 43→47): The alias-banning guidance
// in attempt 47 heavily over-constrained the model, hurting both accuracy and syntax.
// The 141/300 semantic mismatches in attempt 43 (the best) follow a distinct pattern:
// the model generates very short, grammar-complete SQL (e.g., "SELECT city") in Phase 3,
// hits EOS after 1–3 constrained tokens, and then CloseSpanWithinBudget (budget=80)
// immediately closes at that already-complete-but-incomplete-semantically prefix because
// the SQL grammar marks "SELECT city" as a valid complete parse. With budget=80 and the
// span already marked complete, CloseSpanWithinBudget exits after ~1–2 tokens, producing
// wrong SQL. The "avg 9.86 tokens, max 79" metric confirms this: nearly all cost is the
// Phase1+Phase2 preamble plus a trivial Phase4 close.
//
// Fix (two changes from attempt 43, nothing else):
// 1. Remove the IsCompletePrefix early-close in Phase 3 AND the EOS→IsCompletePrefix→Close
//    path in Phase 3. When EOS fires in Phase 3, just break WITHOUT closing. This defers
//    closure to Phase 4 regardless of whether the short SQL is "grammar-complete."
// 2. Increase Phase 4 CloseSpanWithinBudget budget from 80 to 250. CloseSpanWithinBudget
//    is dead-end-aware: it tracks the LONGEST complete prefix seen, continuing well past
//    short complete parses, generating FROM/WHERE/GROUP BY/HAVING/ORDER BY as needed.
//    With 250 steps it can generate the full correct SQL starting from "SELECT city" and
//    close at the longest valid complete parse found.
//
// Guidance: Return EXACTLY to attempt 43's guidance (no alias-banning). The schema-
// grounding boost (6.0) via GroupBoostedConstrainedStep in Phase 3 is preserved to help
// the model pick the right table/column names when generating SQL tokens.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so we can only set
//   insideConstrainedOut := true when RenderedEndsWith fires, at which point we set
//   currentConstrainedOut := [] which satisfies IsValidPrefix([]) by precondition.
//   On EOS path, insideConstrainedOut stays false → implication vacuous. ✓
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut. Helper guarantees
//   insideOut := true and currentOut := []; IsValidPrefix([]) holds by precondition. ✓
//
// Phase 3 main loop (no IsCompletePrefix check):
//   GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus EOS.
//   Non-EOS path: AppendConstrainedToken extends currentConstrainedOut by exactly one
//   parser-valid token, preserving IsValidPrefix by the parser extension contract. ✓
//   EOS path: we break without mutating state → invariant unchanged. ✓
//
// Phase 4 CloseSpanWithinBudget: Postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). Net ≤ 1 token per +1 step. ✓
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   Net 1:1. ✓
// Phase 3: Each iteration increments steps by 1 (GroupBoostedConstrainedStep) and
//   appends at most 1 token (0 on EOS, 1 on non-EOS). Net ≤ 1 token per +1 step. ✓
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + budget.
//   We set steps := steps_before + closeBudget where closeBudget ≤ 250 ≤ remaining.
//   So steps_after ≤ maxSteps and |generated| <= |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let the model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-token group boosting.
// NO early IsCompletePrefix close: we let the model generate until EOS naturally,
// then fall through to Phase 4 regardless of parse completeness.
// Reserve 250 steps for Phase 4 CloseSpanWithinBudget.
while steps + 250 < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.GroupBoostedConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
  );
  steps := steps + 1;
  if next == eosToken {
    // Do NOT close here even if IsCompletePrefix; let Phase 4 find the longest complete parse
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Use CloseSpanWithinBudget with a large budget (250) so it can generate
// beyond any short grammar-complete prefix (e.g., "SELECT city") and track the
// longest complete SQL parse before closing with ">>".
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 250 {
    closeBudget := remaining;
  } else {
    closeBudget := 250;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

